 void SyncActors(){var wanted=new HashSet<string>();var used=new HashSet<string>();foreach(var a in model.Actors){wanted.Add(a.id);bool staff=a.kind==ActorKind.Staff;int role=(a.role=="cook"||a.role=="barista")?1:a.role=="housekeeper"?2:0;if(!actors.TryGetValue(a.id,out var rig)){rig=new GodotCatRig(geometry,renderRoot,staff?"staff":a.kind==ActorKind.DayVisitor?"neighbors":"cats",(staff?role:a.kind==ActorKind.DayVisitor?a.visitorIndex%6:Math.Abs(a.catId)%18).ToString(),a.catId);rig.Root.localScale=Vector3.one*.83f;var collider=rig.Root.gameObject.AddComponent<BoxCollider>();collider.center=new Vector3(0,.6f,0);collider.size=new Vector3(.85f,1.3f,1.05f);rig.Root.gameObject.AddComponent<WorldPick>().catId=a.kind==ActorKind.Guest?a.catId:-1;var builtDrink=geometry.Build(rig.Root,geometry.Recipe("actorExtras","drink"));builtDrink.name="Milkshake";builtDrink.gameObject.SetActive(false);actors.Add(a.id,rig);}rig.Root.gameObject.SetActive(a.kind!=ActorKind.DayVisitor||(neighborhoods.TryGetValue(currentMap,out var street)&&street.IsVisitorVisible(a.visitorIndex)));var at=new Vector3(a.x*Unit,GroundY,a.z*Unit);bool walking=a.action.StartsWith("walk")||a.action=="wander";float face=a.facing;FurniturePose(a,ref at,ref face);if(staff&&role!=2)StaffDeskPose(a,rig,ref at);rig.Root.localPosition=at;rig.Root.localRotation=Quaternion.Euler(0,face*Mathf.Rad2Deg,0);rig.Advance(Time.deltaTime,model.State.settings.motion,a.action=="sunbathe"?"sleep":a.action=="sit"?"rest":a.action,walking,!string.IsNullOrEmpty(a.gesture)?a.gesture:a.action=="play"?"play_object":new[]{"dig","scratch","peek","knead","serve","handoff"}.Contains(a.action)?a.action:"",(a.gesture=="talk"||a.gesture=="happy")?a.speechElapsed:a.activityElapsed,staff,role);rig.Speech(!string.IsNullOrEmpty(a.speech)?a.speech:a.action=="order"?"One shake, please":a.action=="serve"?"Coming right up":a.action=="drink"?"mmm…":a.action=="sunbathe"?a.name+" found a sunny spot!":a.action=="sleep"?"z z z":a.action=="greet"?"Checking in":