 void FurniturePose(ActorSnapshot a,ref Vector3 at,ref float face){if(a.kind==ActorKind.Staff||a.action.StartsWith("walk")||!objects.TryGetValue(a.venueId??"",out var node))return;var o=model.State.objects.FirstOrDefault(x=>x.id==a.venueId);if(o==null)return;var d=Catalog.Find(o.itemId);var occupants=model.Actors.Where(x=>x.venueId==a.venueId&&!x.action.StartsWith("walk")&&x.kind!=ActorKind.Staff).OrderBy(x=>x.catId).ToArray();int slot=Array.FindIndex(occupants,x=>x.id==a.id);Vector3 local;switch(d.shape){case "cafe_stool":local=new Vector3(0,.78f,.04f);break;case "cloud_sofa":case "lounge_sofa":case "bench":local=new Vector3((slot-(occupants.Length-1)*.5f)*.8f,.59f,d.depth*Unit*.12f);break;case "mat":case "sun_cushion":case "heated":case "blanket":case "cave":case "canopy_bed":local=new Vector3(0,.55f,d.depth*Unit*.11f);break;case "perch":local=new Vector3(0,1.05f,.06f);break;case "picnic":local=new Vector3(d.width*Unit*.32f*(slot<2?-1:1),.26f,d.depth*Unit*.32f*(slot%2==0?-1:1));break;case "table":local=new Vector3((slot/2-(Mathf.Ceil(occupants.Length/2f)-1)*.5f)*.8f,.5f,d.depth*Unit*.4f*(slot%2==0?-1:1));break;default:return;}at=ToAuthored(node.TransformPoint(local));face=-o.rotation*Mathf.PI/2;}
