 static Transform Group(Transform parent,string name){var t=new GameObject(name).transform;t.SetParent(parent,false);return t;}static void DisposeNode(Transform t){if(t){t.gameObject.SetActive(false);Destroy(t.gameObject);}}static Color Hex(string c){ColorUtility.TryParseHtmlString(c.StartsWith("#")?c:"#"+c,out var v);return v;}static string Shade(string c,float f){var v=Hex(c);v=f>=0?Color.Lerp(v,Color.white,f):v*(1+f);return ColorUtility.ToHtmlStringRGB(v);}
