 void Bake(Transform root){var groups=new Dictionary<Material,List<CombineInstance>>();var old=new List<GameObject>();foreach(var f in root.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<MeshRenderer>();if(!r||f.GetComponent<TextMesh>())continue;if(!groups.TryGetValue(r.sharedMaterial,out var list))groups[r.sharedMaterial]=list=new List<CombineInstance>();list.Add(new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix});old.Add(f.gameObject);}foreach(var g in groups){var t=Group(root,"Batched cuboids");var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(g.Value.ToArray());t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=g.Key;t.gameObject.AddComponent<GeneratedVoxelMesh>().OwnedMesh=mesh;}foreach(var g in old){g.SetActive(false);Destroy(g);}}
